#!/usr/bin/env python3
"""Publish measured progress without labeling pending execution ITP complete."""
import argparse,collections,json,statistics
from test_read_variants import ROOT,save,sha
from publish_abs_tool_results import stage
from evaluation_expectations import expected,matches
from attach_cell_leak_itp import mode_costs

def main(group):
 g=ROOT/'benchmark/programs'/group;b=ROOT/'benchmark/results'/group;plan=json.loads((g/'evaluation-plan.json').read_text());run=b/plan['run_id'];data=json.loads((run/'results.json').read_text());rows=data['runs'];rel=lambda p:str(p.relative_to(ROOT));variants={json.loads(p.read_text())['id']:json.loads(p.read_text()) for p in (g/'variants').glob('*/manifest.json')}
 nativepath=b/'20261016-primary-native/receipt.json';n=json.loads(nativepath.read_text());proofpath=b/'20261016-qcp-verify-complete/receipt.json';proof=json.loads(proofpath.read_text());assert proof['status']=='VERIFIED_KERNEL_CHECKED' and proof['kernel_check']['exit_code']==0
 for lang,vid in [('cn',plan['primary_cn_variant']),('qcp',plan['primary_qcp_variant'])]:assert sha(ROOT/variants[vid]['files'][lang]['path'])==n[lang+'_source_sha256']
 cm=n['cn'];assert cm['exit_code']==0
 save(b/'cn/results.json',{'schema':'tespec-group-tool-result/v1','tool':'cn','program_group':group,'verdict':'VERIFIED','primary_variant':plan['primary_cn_variant'],'source':variants[plan['primary_cn_variant']]['files']['cn'],'evidence':rel(nativepath),'original_measurement':cm,'scope':'All non-trusted functions in original designated CN translation unit.'})
 save(b/'cn/statistics.json',{'wall_seconds':cm['wall_seconds'],'peak_process_resident_mib':cm['resources']['max_process_rss_kib']/1024,'tokens':0,'model_calls':0,'verification_runs_counted':1})
 qs=dict(proof['metrics']);qs['stages']=[stage('vc_generation_and_automatic_processing',qs['native_auto_wall_seconds'],qs['native_peak_process_rss_kib']/1024),stage('agent_proof_filling',qs['model_wall_seconds'],qs['model_client_peak_working_set_bytes']/1048576,qs['tokens']),stage('coq_compilation_and_assumption_audit',qs['coq_compile_audit_wall_seconds'],max(x['resources']['max_process_rss_kib'] for x in proof['compilation'])/1024),stage('independent_kernel_check',qs['kernel_wall_seconds'],proof['kernel_check']['resources']['max_process_rss_kib']/1024)];qs['full_verification_complete']=True
 save(b/'qcp/results.json',{'schema':'tespec-group-tool-result/v1','tool':'qcp','program_group':group,'verdict':proof.get('verdict','VERIFIED_KERNEL_CHECKED'),'primary_variant':plan['primary_qcp_variant'],'source':variants[plan['primary_qcp_variant']]['files']['qcp'],'receipt':rel(proofpath),'obligations':len(proof['obligations']),'assumptions':proof['assumptions'],'scope':proof['scope']});save(b/'qcp/statistics.json',qs)
 modes={}
 for mode in ['off','on']:
  key='tespec_'+mode;ms=[r[key] for r in rows];times=[m['wall_seconds'] for m in ms];peaks=[m['resources']['max_process_rss_kib']/1024 for m in ms];needed=[m for m in ms if m['status']=='UNKNOWN'];done=[m for m in needed if m.get('itp')]
  d={'native_status_counts':dict(collections.Counter(m['status'] for m in ms)),'final_status_counts':dict(collections.Counter(m.get('final_status',m['status']) for m in ms)),'expected_matches':sum(matches(r,key) for r in rows),'execution_attempts_count':len(ms),'execution_wall_seconds_total':sum(times),'mean_execution_wall_seconds':statistics.mean(times),'mean_execution_peak_rss_mib':statistics.mean(peaks),'maximum_execution_peak_rss_mib':max(peaks),'executions_requiring_itp_for_verdict':len(needed),'completed_independent_itp_executions':len(done),'pending_independent_itp_executions':len(needed)-len(done),'itp_wall_seconds_counted':None if len(done)<len(needed) else sum(m['itp']['metrics']['total_seconds'] for m in done),'itp_completed_subset_wall_seconds':sum(m['itp']['metrics']['total_seconds'] for m in done),'spatial_smt_queries_attempted':sum(json.loads((ROOT/m['report']).read_text())['results'][0].get('spatial_smt',{}).get('attempted',0) for m in ms)};modes[mode]=d
 save(run/'statistics.json',{'schema':'tespec-group-spatial-smt-comparison/v1','program_group':group,'case_pairs':len(rows),'results_sha256':sha(run/'results.json'),'modes':modes,'complete':False,'certificate':'NOT_CHECKED','itp_scope':'Independent Coq certificates apply only to completed per-execution tasks, not native SMT decisions.'});(run/'comparison.md').write_text('# '+group+'：评测进行中\n\n两模式原始结果与逐例预期已保存。OFF 所需 ITP 未全部完成，不能把 UNKNOWN 算作成功。成本和已完成独立证据见 statistics.json 与 ../20261016-itp-per-execution/index.json。\n')
 fs={'instrument_compile_initial_execution_wall_seconds_total':sum(r['fulminate_pipeline']['wall_seconds'] for r in rows),'test_execution_wall_seconds_total':sum(r['fulminate_test']['wall_seconds'] for r in rows),'pipeline_peak_process_rss_kib':max(r['fulminate_pipeline']['resources']['max_process_rss_kib'] for r in rows),'test_peak_process_rss_kib':max(r['fulminate_test']['resources']['max_process_rss_kib'] for r in rows),'tokens':0,'model_calls':0};save(b/'fulminate/statistics.json',fs)
 for tool,key in [('fulminate','fulminate_test'),('tespec','tespec_off')]:
  save(b/tool/'results.json',{'schema':'tespec-group-tool-result/v1','tool':tool,'program_group':group,'summary':{'case_pairs':len(rows),'correct':sum(matches(r,key) for r in rows),'native_status_counts':dict(collections.Counter(r[key]['status'] for r in rows))},'evidence':rel(run/'results.json'),'evaluation_complete':tool=='fulminate','cases':[{'variant':r['variant'],'paired_qcp_variant':r['paired_qcp_variant'],'case':r['case'],'initial':r['initial'],'expected':expected(r,key),'raw_actual':r[key]['status'],'actual':r[key].get('final_status',r[key]['status']),'matches_expected':matches(r,key),'itp':r[key].get('itp')} for r in rows]})
 off=modes['off'];save(b/'tespec/statistics.json',{'execution_wall_seconds_total':off['execution_wall_seconds_total'],'execution_peak_process_rss_kib':int(off['maximum_execution_peak_rss_mib']*1024),'tokens':None,'model_calls':None,'itp_required_executions':off['executions_requiring_itp_for_verdict'],'itp_completed_executions':off['completed_independent_itp_executions'],'itp_evidence_index':rel(b/'20261016-itp-per-execution/index.json'),'stages':[stage('test_execution_and_vc_generation',off['execution_wall_seconds_total'],off['maximum_execution_peak_rss_mib'])]+[stage(k,None,None,None) for k in ['agent_proof_filling','coq_compilation_and_assumption_audit','independent_kernel_check']]})
 manifest=json.loads((g/'manifest.json').read_text());manifest.update(primary_variant=plan['primary_cn_variant'],primary_selection_status='BOUND_TO_PAIRED_VERIFICATION',primary_verification={'cn_status':'VERIFIED','qcp_status':proof.get('verdict','VERIFIED_KERNEL_CHECKED'),'paired_qcp_variant':plan['primary_qcp_variant'],'qcp_complete_proof_receipt':rel(proofpath),'assumptions':proof['assumptions']},test_modes_statistics=rel(run/'statistics.json'));manifest['tool_results']={t:{'results':rel(b/t/'results.json'),'statistics':rel(b/t/'statistics.json')} for t in ['cn','qcp','fulminate','tespec']};save(g/'manifest.json',manifest)
 save(b/'index.json',{'program_group':group,'evaluation_plan':rel(g/'evaluation-plan.json'),'evaluation':rel(run/'results.json'),'qcp_receipt':rel(proofpath),'cost_table':rel(b/'result-cost.md'),'complete':False,'pending':'Remaining independent ITP tasks; raw UNKNOWN preserved.'})
 print('Published incomplete progress',group,'Fulminate',sum(matches(r,'fulminate_test') for r in rows),'/',len(rows),'teSpec OFF final so far',off['expected_matches'],'/',len(rows),flush=True)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--group',required=True);a=p.parse_args();main(a.group)
 from collect_tespec_unexpected import collect
 collect()
 from build_group_cost_tables import main as rebuild
 rebuild()
 from refresh_benchmark_progress import refresh
 refresh()
